SELECT [TB Time Keeping].Bill_ID, [TB Time Keeping].[Bill Sent], [TB Time Keeping].[Bill Paid], [TB Time Keeping].[Bill Closed], [TB Time Keeping].[BilL Closed Date], [TB Time Keeping].Discount, [TB Time Keeping].[Bill Number], [TB Time Keeping].IANumber, [TB Time Keeping].[Bill Open], [TB Time Keeping].TimeNotes, tblCase.*, [TB Time Keeping].TKLocked, [TB Time Keeping].InvoiceTotalAdvance, [TB Time Keeping].InvoiceExceedsTrust, [TB Time Keeping].StatementLessTrust, [TB Time Keeping].TrustatClose, [TB Time Keeping].InvoiceNoAdvance, [TB Time Keeping].AdvBalanceatClose, [TB Time Keeping].ARatClose, [TB Time Keeping].ReplenishBalanceatClose, [TB Time Keeping].OutsAdvDue, [TB Time Keeping].AdvFeesBal, [TB Time Keeping].AdvCostBal, [TB Time Keeping].InvoiceAdvCostFee, [TB Time Keeping].InvoiceCostHold
FROM tblCase INNER JOIN [TB Time Keeping] ON tblCase.CaseID = [TB Time Keeping].CaseID
ORDER BY [TB Time Keeping].Bill_ID DESC;